// Job represents a unit of work to be processed.
type Job struct {
	ID    int
	Value int
}

// Result holds the outcome of processing a job.
type Result struct {
	JobID int
	Value int
	Err   error
}

// WorkerPool manages a pool of workers processing jobs from a channel.
type WorkerPool struct {
	numWorkers int
	jobs       <-chan Job
	process    func(ctx context.Context, job Job) (int, error)
}

// NewWorkerPool creates a new worker pool.
func NewWorkerPool(numWorkers int, jobs <-chan Job, process func(ctx context.Context, job Job) (int, error)) *WorkerPool {
	return &WorkerPool{
		numWorkers: numWorkers,
		jobs:       jobs,
		process:    process,
	}
}

